) / (1000000)) * (1000000)) ELSE ROUND((CASE WHEN ((SUM(CASE WHEN OPPORTUNITIES.STATUS = 'Won' THEN OPPORTUNITIES.COL_VALUE END::FLOAT))) IS NULL AND ((SUM(CASE WHEN (OPPORTUNITIES.STATUS = 'Open') AND (TRY_TO_NUMBER(LEFT(OPPORTUNITIES.SALES_STAGE, 1)) >= 2) THEN OPPORTUNITIES.COL_VALUE END::FLOAT)) * 0.6) IS NULL THEN NULL ELSE COALESCE((SUM(CASE WHEN OPPORTUNITIES.STATUS = 'Won' THEN OPPORTUNITIES.COL_VALUE END::FLOAT)), 0) + ((SUM(CASE WHEN (OPPORTUNITIES.STATUS = 'Open') AND (TRY_TO_NUMBER(LEFT(OPPORTUNITIES.SALES_STAGE, 1)) >= 2) THEN OPPORTUNITIES.COL_VALUE END::FLOAT)) * 0.6) END) / (100000)) * (100000) END, 0),
		OPPORTUNITY_FORECAST_ADJUSTMENT.FORECAST_ADJUSTMENT_VALUE as IFF(COUNT(DISTINCT OPPORTUNITY_FORECAST_ADJUSTMENT.FORECAST_ADJUSTMENT) + MAX(IFF(OPPORTUNITY_FORECAST_ADJUSTMENT.FORECAST_ADJUSTMENT IS NULL, 1, 0)) = 1, MAX(OPPORTUNITY_FORECAST_ADJUSTMENT.FORECAST_ADJUSTMENT), 0),
		OPPORTUNITIES.FORECAST_BY_WIN_LOSS_RATIO as (CASE WHEN ((SUM(CASE WHEN OPPORTUNITIES.STATUS = 'Open' THEN OPPORTUNITIES.COL_VALUE END::FLOAT))) IS NULL AND ((SUM(CASE WHEN OPPORTUNITIES.STATUS = 'Open' THEN OPPORTUNITIES.COL_VALUE END::FLOAT)) * (0) / 100) IS NULL THEN NULL ELSE COALESCE((SUM(CASE WHEN OPPORTUNITIES.STATUS = 'Open' THEN OPPORTUNITIES.COL_VALUE END::FLOAT)), 0) + ((SUM(CASE WHEN OPPORTUNITIES.STATUS = 'Open' THEN OPPORTUNITIES.COL_VALUE END::FLOAT)) * (0) / 100) END) * ((COUNT(CASE WHEN OPPORTUNITIES.STATUS = 'Won' THEN OPPORTUNITIES.OPPORTUNITYSEQ END)) / NULLIF(((COUNT(CASE WHEN OPPORTUNITIES.STATUS = 'Won' THEN OPPORTUNITIES.OPPORTUNITYSEQ END))) + ((COUNT(CASE WHEN OPPORTUNITIES.STATUS = 'Lost' THEN OPPORTUNITIES.OPPORTUNITYSEQ END))), 0)),
